def lstm_cell(input, hx, w_ih, w_hh, b_ih=None, b_hh=None):
    """Fully fused LSTM cell: single Triton kernel for GEMM + activations + state update.

    Computes:
        gates = input @ w_ih.T + h_prev @ w_hh.T + b_ih + b_hh
        i, f, g, o = sigmoid, sigmoid, tanh, sigmoid (gates split by hidden_size)
        cy = f * cx + i * g
        hy = o * tanh(cy)

    Args:
        input: Input tensor of shape (batch, input_size)
        hx: List of [h_prev, c_prev], each of shape (batch, hidden_size)
        w_ih: Input-hidden weight of shape (4 * hidden_size, input_size)
        w_hh: Hidden-hidden weight of shape (4 * hidden_size, hidden_size)
        b_ih: Optional input-hidden bias of shape (4 * hidden_size,)
        b_hh: Optional hidden-hidden bias of shape (4 * hidden_size,)

    Returns:
        hy: New hidden state of shape (batch, hidden_size)
        cy: New cell state of shape (batch, hidden_size)
    """
    logger.debug("GEMS LSTM_CELL FUSED")

    h_prev, c_prev = hx[0], hx[1]
    batch_size = input.shape[0]
    input_size = input.shape[1]
    hidden_size = h_prev.shape[1]

    # Ensure contiguous layout for predictable strides
    input = input.contiguous()
    h_prev = h_prev.contiguous()
    c_prev = c_prev.contiguous()
    w_ih = w_ih.contiguous()
    w_hh = w_hh.contiguous()

    # Allocate output tensors
    hy = torch.empty((batch_size, hidden_size), device=input.device, dtype=input.dtype)
    cy = torch.empty((batch_size, hidden_size), device=input.device, dtype=input.dtype)

    HAS_BIAS = b_ih is not None and b_hh is not None

    # Use dummy pointer for bias if not present
    if not HAS_BIAS:
        b_ih = torch.empty(0, device=input.device, dtype=input.dtype)
        b_hh = torch.empty(0, device=input.device, dtype=input.dtype)

    # Grid: tile over (batch, hidden_size)
    def grid(META):
        return (
            triton.cdiv(batch_size, META["BLOCK_M"]),
            triton.cdiv(hidden_size, META["BLOCK_N"]),
        )

    lstm_cell_fused_kernel[grid](
        input,
        h_prev,
        c_prev,
        w_ih,
        w_hh,
        b_ih,
        b_hh,
        hy,
        cy,
        batch_size,
        input_size,
        hidden_size,
        input.stride(0),
        input.stride(1),
        h_prev.stride(0),
        h_prev.stride(1),
        c_prev.stride(0),
        c_prev.stride(1),
        w_ih.stride(0),
        w_ih.stride(1),
        w_hh.stride(0),
        w_hh.stride(1),
        hy.stride(0),
        hy.stride(1),
        cy.stride(0),
        cy.stride(1),
        HAS_BIAS=HAS_BIAS,
    )

    return hy, cy
